// Dedupe by job_id, but keep every term that found the job (not just the first)
const byId = new Map();

for (const item of $input.all()) {
  const j = item.json;
  const kept = byId.get(j.job_id);
  if (!kept) {
    byId.set(j.job_id, { json: { ...j, search_terms: [...(j.search_terms ?? [])] } });
  } else {
    for (const t of j.search_terms ?? []) {
      if (!kept.json.search_terms.includes(t)) kept.json.search_terms.push(t);
    }
  }
}

return [...byId.values()];

