// Compute Verdict — Run Once for All Items
const ROS_BUYOUT_MIN_PHP = 60000;   // minimum monthly pay for a non-ROS job
const PASS_SCORE = 5;
const USD_PHP = 63;                 // approximate; update occasionally
const MODEL = 'gemini-3.1-flash-lite';
const MAX_AGE_DAYS = 31;
const MAX_OFFICE_DAYS = 2;          // hybrid above this is gated as 'OFFICE 3+ DAYS'
const SALARY_FULL = 45000;          // score_salary 2 at or above
const SALARY_PARTIAL = 38000;       // score_salary 1 at or above
const GATES = ['OLD JOB POST', 'LOCATION FAR', 'ONSITE', 'OFFICE 3+ DAYS', 'STACK MISMATCH', 'NOT DEV ROLE'];
const PER_MONTH = { yearly: 1/12, monthly: 1, weekly: 52/12, daily: 22, hourly: 160 };
const RULES_VERSION = 6;

// Flags this node owns. Any copy the LLM emits is discarded and recomputed.
const CODE_FLAGS = ['OLD JOB POST', 'DATE UNKNOWN', 'ONSITE', 'HYBRID', 'OFFICE 3+ DAYS',
  'LOCATION FAR', 'LOCATION UNCLEAR', 'SETUP UNCLEAR', 'SALARY UNKNOWN', 'SALARY BELOW FLOOR', 'ROS BUYOUT', 'STACK MISMATCH', 'REACH ROLE', 'NESTJS MATCH', 'NOT DEV ROLE'];

const clamp = (n, max) => Math.max(0, Math.min(max, Math.round(Number(n)) || 0));
const toMonthlyPhp = (amt, interval, currency) => {
  if (amt == null || !PER_MONTH[interval]) return null;
  const fx = currency === 'PHP' ? 1 : currency === 'USD' ? USD_PHP : null;
  return fx ? Math.round(Number(amt) * PER_MONTH[interval] * fx) : null;
};

return $input.all().map(item => {
  const j = item.json;
  const llm_flags = (Array.isArray(j.llm_flags) ? j.llm_flags : []).filter(f => !CODE_FLAGS.includes(f));

  // 1. Post date
  const postedMs = j.posted_at ? new Date(j.posted_at).getTime() : NaN;
  if (Number.isNaN(postedMs)) llm_flags.push('DATE UNKNOWN');
  else if ((Date.now() - postedMs) / 86_400_000 > MAX_AGE_DAYS) llm_flags.push('OLD JOB POST');

  // 2. Work setup and location: from the LLM's required fields, never from is_remote
  const work_setup = ['remote', 'hybrid', 'onsite'].includes(j.work_setup) ? j.work_setup : 'unclear';
  const office_days_per_week = work_setup === 'hybrid' && Number.isInteger(j.office_days_per_week)
    ? j.office_days_per_week : null;

  if (work_setup === 'onsite') llm_flags.push('ONSITE');
  else if (work_setup === 'hybrid') {
    llm_flags.push(office_days_per_week !== null && office_days_per_week > MAX_OFFICE_DAYS ? 'OFFICE 3+ DAYS' : 'HYBRID');
  } else if (work_setup === 'unclear') llm_flags.push('SETUP UNCLEAR');

  if (work_setup !== 'remote') {
    if (j.office_in_range === false) llm_flags.push('LOCATION FAR');
    else if (j.office_in_range !== true) llm_flags.push('LOCATION UNCLEAR');
  }

  // 3. Salary: JobSpy first, the LLM's stated figure as fallback; scored by rule
  const fromJobspy = toMonthlyPhp(j.min_amount ?? j.max_amount, j.interval, j.currency);
  const fromLlm = j.salary_monthly_php_stated == null ? null
                : Math.round(Number(j.salary_monthly_php_stated)) || null;
  const salary_monthly_php = fromJobspy ?? fromLlm;
  const salary_source = fromJobspy != null ? 'jobspy' : fromLlm != null ? 'llm' : null;

  let salaryScore = 0;
  if (salary_monthly_php == null) llm_flags.push('SALARY UNKNOWN');
  else if (salary_monthly_php >= SALARY_FULL) salaryScore = 2;
  else if (salary_monthly_php >= SALARY_PARTIAL) salaryScore = 1;
  else llm_flags.push('SALARY BELOW FLOOR');

  // 3b. Stack: an out-of-ecosystem primary stack is a hard no. Check the raw value,
  // not the clamped one, so a missing or garbled score never gates a job by accident.
  if (j.score_stack === 0) llm_flags.push('STACK MISMATCH');

  // 3c. Role type: same fail-open rule. Only an explicit false gates.
  if (j.dev_role === false) llm_flags.push('NOT DEV ROLE');

  // 4. Gates zero the total, not the subscores, so gated jobs keep their would-be scores
  const gated = llm_flags.some(f => GATES.includes(f));
  const scores = {
    score_stack:      clamp(j.score_stack, 3),
    score_experience: clamp(j.score_experience, 2),
    score_flags:      clamp(j.score_flags, 3),
    score_salary:     salaryScore,
  };

  if (scores.score_experience === 0) llm_flags.push('REACH ROLE');
  if (/\bnest\.?js\b/i.test(`${j.title ?? ''} ${j.description ?? ''}`)) llm_flags.push('NESTJS MATCH');

  const potential = Object.values(scores).reduce((a, b) => a + b, 0);
  const llm_score = gated ? 0 : potential;

  // 5. ROS: unexpected values become 'unverified', never silently 'pass'
  const ros_status = ['pass', 'unverified', 'fail'].includes(j.ros_status) ? j.ros_status : 'unverified';
  const buyout = ros_status === 'fail' && salary_monthly_php != null && salary_monthly_php >= ROS_BUYOUT_MIN_PHP;
  if (buyout) llm_flags.push('ROS BUYOUT');

  // 6. Decision
  const llm_apply = !gated && llm_score >= PASS_SCORE && (ros_status !== 'fail' || buyout);

  return { json: {
    ...j, ...scores, llm_flags, llm_score, llm_apply,
    ros_status, ros_pass: ros_status !== 'fail',
    work_setup, office_days_per_week,
    salary_monthly_php, salary_source,
    llm_model: MODEL, rules_version: RULES_VERSION
  }};
});
